draw:
var pad = 34;
var top = 26;
var floorY = H - 22;
var tankX = pad, tankW = (W - pad * 2) * 0.52;
var depthMax = 30;
var sy = (floorY - top) / depthMax;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textBaseline = "middle";

// tank walls and water
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1.5;
ctx.beginPath();
ctx.moveTo(tankX, top - 8);
ctx.lineTo(tankX, floorY);
ctx.lineTo(tankX + tankW, floorY);
ctx.lineTo(tankX + tankW, top - 8);
ctx.stroke();

// wavy surface
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1.5;
ctx.beginPath();
for (var i = 0; i <= 40; i++) {
  var x = tankX + tankW * i / 40;
  var y = top + 2.0 * Math.sin(i * 0.55 + t * 1.6);
  i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
}
ctx.stroke();
ctx.fillStyle = C.faint;
ctx.fillText("surface, p = p0", tankX + 6, top - 14);

// depth marker
var d = p.depth;
var dy = top + d * sy;
ctx.strokeStyle = C.accent;
ctx.lineWidth = 1.5;
ctx.setLineDash([4, 4]);
ctx.beginPath();
ctx.moveTo(tankX, dy);
ctx.lineTo(tankX + tankW, dy);
ctx.stroke();
ctx.setLineDash([]);

// the column of fluid above the point
ctx.fillStyle = C.faint;
ctx.globalAlpha = 0.25;
ctx.fillRect(tankX + tankW * 0.30, top, tankW * 0.16, d * sy);
ctx.globalAlpha = 1;
ctx.strokeStyle = C.figure;
ctx.strokeRect(tankX + tankW * 0.30, top, tankW * 0.16, d * sy);

var cx = tankX + tankW * 0.38;
// weight arrow of the column
ctx.strokeStyle = C.ink;
ctx.beginPath();
ctx.moveTo(cx, top + d * sy * 0.35);
ctx.lineTo(cx, top + d * sy * 0.35 + 22);
ctx.lineTo(cx - 3.5, top + d * sy * 0.35 + 16);
ctx.moveTo(cx, top + d * sy * 0.35 + 22);
ctx.lineTo(cx + 3.5, top + d * sy * 0.35 + 16);
ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("weight of column", cx + 8, top + d * sy * 0.35 + 12);

ctx.fillStyle = C.accent;
ctx.beginPath();
ctx.arc(cx, dy, 4, 0, Math.PI * 2);
ctx.fill();
ctx.fillText("depth h = " + d.toFixed(1) + " m", tankX + 6, dy + 14);

// graph of pressure vs depth on the right
var gx0 = tankX + tankW + 46, gx1 = W - 14;
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath();
ctx.moveTo(gx0, top);
ctx.lineTo(gx0, floorY);
ctx.lineTo(gx1, floorY);
ctx.stroke();

var pAtm = 101000;
var pMax = pAtm + p.rho * 9.8 * depthMax;
var gw = gx1 - gx0;
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
ctx.beginPath();
for (var k = 0; k <= 60; k++) {
  var hh = depthMax * k / 60;
  var pp = pAtm + p.rho * 9.8 * hh;
  var X = gx0 + gw * pp / pMax;
  var Y = top + hh * sy;
  k === 0 ? ctx.moveTo(X, Y) : ctx.lineTo(X, Y);
}
ctx.stroke();

var pAbs = pAtm + p.rho * 9.8 * d;
var mx = gx0 + gw * pAbs / pMax;
ctx.fillStyle = C.accent;
ctx.beginPath();
ctx.arc(mx, dy, 4, 0, Math.PI * 2);
ctx.fill();
ctx.strokeStyle = C.accent;
ctx.setLineDash([3, 3]);
ctx.beginPath();
ctx.moveTo(gx0, dy);
ctx.lineTo(mx, dy);
ctx.stroke();
ctx.setLineDash([]);

ctx.fillStyle = C.faint;
ctx.fillText("pressure", gx0 + 4, floorY + 12);
ctx.save();
ctx.translate(gx0 - 12, (top + floorY) / 2);
ctx.rotate(-Math.PI / 2);
ctx.textAlign = "center";
ctx.fillText("depth", 0, 0);
ctx.restore();
ctx.textAlign = "left";

out.note = "gauge " + (p.rho * 9.8 * d / 1000).toFixed(1) + " kPa, absolute " +
  (pAbs / 1000).toFixed(1) + " kPa (" + (pAbs / pAtm).toFixed(2) + " atmospheres)";
